[workspace]
members = ["crates/*"]
exclude = [
  "scripts",
  # Needs nightly
  "crates/uv-trampoline",
]
resolver = "2"

[workspace.package]
edition = "2024"
rust-version = "1.97.0"
homepage = "https://pypi.org/project/uv/"
repository = "https://github.com/astral-sh/uv"
authors = ["uv"]
license = "MIT OR Apache-2.0"

[workspace.dependencies]
uv = { version = "0.13.8", path = "crates/uv", default-features = false }
uv-audit = { version = "0.0.100", path = "crates/uv-audit" }
uv-audit-operations = { version = "0.0.100", path = "crates/uv-audit-operations" }
uv-auth = { version = "0.0.100", path = "crates/uv-auth" }
uv-bin-install = { version = "0.0.100", path = "crates/uv-bin-install" }
